.admin-navsearch input{
 width:100%;min-width:0;min-height:39px;padding:0 0;border:0;outline:0;background:transparent;
 color:#E6EDF8;font:500 11.5px/1.4 Inter,"Segoe UI",sans-serif;box-shadow:none!important;
}
