.admin-sr-only{position:absolute!important;width:1px!important;height:1px!important;padding:0!important;margin:-1px!important;overflow:hidden!important;clip:rect(0,0,0,0)!important;white-space:nowrap!important;border:0!important}
.admin-favorites{display:grid;gap:7px;min-width:0;padding:0 0 14px;margin:0 0 2px;border-bottom:1px solid #26364D}
.admin-favorites-heading{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:0 11px 2px}
.admin-favorites-heading>span{font-size:9px;letter-spacing:.15em;line-height:1.5;font-weight:800;color:#8EA1BC}
.admin-favorites-edit{border:1px solid transparent;border-radius:6px;background:transparent;color:#8FA7D1;padding:3px 6px;font:650 10px/1.3 Inter,"Segoe UI",sans-serif;cursor:pointer}
.admin-favorites-edit:hover:not(:disabled){background:#1A2A43;border-color:#30445F;color:#EAF1FF}
.admin-favorites-edit:disabled{opacity:.4;cursor:default}
.admin-favorite-list{display:grid;gap:4px;min-width:0}
.admin-favorites-empty{margin:0;padding:4px 11px;color:#7F91AB;font-size:10.5px;line-height:1.5}
.admin-favorite-item{display:flex;align-items:center;gap:4px;min-width:0;padding-right:4px;border:1px solid transparent;border-radius:10px}
.admin-favorite-item:hover{background:#13223A;border-color:#263B59}
.admin-favorite-link{display:flex;align-items:center;gap:10px;flex:1 1 auto;min-width:0;min-height:37px;padding:7px 9px;border-radius:8px;color:#B7C5D9;font-size:11.5px;line-height:1.35;font-weight:650}
.admin-favorite-link:hover{color:#F6F8FF}
.admin-favorite-link.active{color:#F4F7FF;background:rgba(79,124,255,.13)}
.admin-favorite-icon{display:grid;place-items:center;flex:0 0 20px;width:20px;height:20px;color:#8FA6CB}
.admin-favorite-link.active .admin-favorite-icon{color:#A4BAFF}
.admin-favorite-link>span:last-child{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.admin-favorite-remove{display:none;place-items:center;flex:0 0 27px;width:27px;height:27px;padding:0;border:1px solid transparent;border-radius:8px;background:transparent;color:#95A7C2;cursor:pointer}
.admin-favorite-remove .hf-shell-icon{width:14px;height:14px}
.admin-favorites.is-editing .admin-favorite-remove{display:grid}
.admin-favorites.is-editing .admin-favorite-remove:hover{background:#351D2B;border-color:#693247;color:#FFB8C6}
.admin-nav-item{display:flex;align-items:center;gap:3px;min-width:0}
.admin-nav-item .admin-nav-link{flex:1 1 auto;min-width:0}
.admin-nav-fav-toggle{display:grid;place-items:center;flex:0 0 29px;width:29px;height:31px;padding:0;border:1px solid transparent;border-radius:8px;background:transparent;color:#7587A2;cursor:pointer;opacity:.72;transition:background .15s ease,border-color .15s ease,color .15s ease,opacity .15s ease}
.admin-nav-fav-toggle .hf-shell-icon{width:15px;height:15px;stroke-width:1.7}
