.admin-nav-fav-toggle[aria-pressed="true"]{opacity:1;color:#E8BD6B}
.admin-nav-fav-toggle[aria-pressed="true"] .hf-shell-icon{fill:currentColor}
.admin-nav-fav-toggle[aria-pressed="true"] .hf-shell-icon path{fill:currentColor}
