.admin-nav-item.is-search-match .admin-nav-text{font-weight:750}
.admin-nav-group{min-width:0}
.admin-nav-group .admin-nav-links{min-width:0}
.admin-nav-label{user-select:none}
.admin-favorites.is-empty{padding-bottom:12px}
