}
html[data-admin-theme="light"] body{background:#F2F0EA}
html[data-admin-theme="dark"] body{background:#222130}
html[data-admin-theme="light"] .admin-sidebar{background:#FFFDF8;box-shadow:4px 0 18px rgba(43,42,61,.025)}
