.hf-card{background:var(--hf-paper);box-shadow:var(--hf-shadow)}
.hf-table th{background:var(--hf-table-head)}
.hf-table tbody tr:hover td{background:var(--hf-table-hover)}
.hf-input,.hf-select,.hf-textarea{background:var(--hf-control-surface)}
.hf-table-wrap{overscroll-behavior-x:contain;scrollbar-width:thin}
.hf-table-wrap:focus-visible{outline:3px solid var(--hf-focus);outline-offset:3px}
.hf-input[aria-invalid="true"],.hf-select[aria-invalid="true"],.hf-textarea[aria-invalid="true"]{border-color:var(--hf-red);box-shadow:0 0 0 3px #B4453A22}
.hf-data-note.hf-error{color:var(--hf-red)}
.hf-table tbody tr:focus-within td{background:var(--hf-table-hover)}
