.admin-sidebar,
html[data-admin-theme] .admin-sidebar{
  position:sticky;
  isolation:isolate;
  overflow-x:hidden;
  color:#F8F7FF !important;
  background:
    radial-gradient(ellipse at 96% 4%,rgba(255,116,153,.38) 0%,transparent 31%),
